-- Foreign keys: the database itself now refuses an order for a branch, table, dish or staff member that does not exist.
-- audit_logs.entity_id and notifications.entity_id point at different tables depending on the row, so they have none.

alter table areas add constraint fk_areas_branch_id foreign key (branch_id) references branches (id);
alter table audit_logs add constraint fk_audit_logs_branch_id foreign key (branch_id) references branches (id);
alter table audit_logs add constraint fk_audit_logs_staff_id foreign key (staff_id) references staffs (id);
alter table branch_inventories add constraint fk_branch_inventories_branch_id foreign key (branch_id) references branches (id);
