alter table branch_menu_items add constraint fk_branch_menu_items_menu_item_id foreign key (menu_item_id) references menu_items (id);
alter table branches add constraint fk_branches_manager_id foreign key (manager_id) references staffs (id);
alter table code_sequences add constraint fk_code_sequences_branch_id foreign key (branch_id) references branches (id);
alter table deliveries add constraint fk_deliveries_order_id foreign key (order_id) references orders (id);
alter table deliveries add constraint fk_deliveries_shipper_staff_id foreign key (shipper_staff_id) references staffs (id);
alter table dining_tables add constraint fk_dining_tables_area_id foreign key (area_id) references areas (id);
alter table menu_items add constraint fk_menu_items_category_id foreign key (category_id) references menu_categories (id);
