alter table order_items add constraint fk_order_items_order_id foreign key (order_id) references orders (id);
alter table order_items add constraint fk_order_items_menu_item_id foreign key (menu_item_id) references menu_items (id);
alter table order_items add constraint fk_order_items_cooked_by foreign key (cooked_by) references staffs (id);
alter table order_items add constraint fk_order_items_served_by foreign key (served_by) references staffs (id);
alter table orders add constraint fk_orders_branch_id foreign key (branch_id) references branches (id);
alter table orders add constraint fk_orders_table_id foreign key (table_id) references dining_tables (id);
alter table orders add constraint fk_orders_customer_id foreign key (customer_id) references customers (id);
