alter table payments add constraint fk_payments_order_id foreign key (order_id) references orders (id);
alter table payments add constraint fk_payments_received_by foreign key (received_by) references staffs (id);
alter table payments add constraint fk_payments_refunded_by foreign key (refunded_by) references staffs (id);
alter table point_transactions add constraint fk_point_transactions_customer_id foreign key (customer_id) references customers (id);
alter table point_transactions add constraint fk_point_transactions_order_id foreign key (order_id) references orders (id);
alter table promotion_branches add constraint fk_promotion_branches_promotion_id foreign key (promotion_id) references promotions (id);
alter table promotion_branches add constraint fk_promotion_branches_branch_id foreign key (branch_id) references branches (id);
alter table purchase_orders add constraint fk_purchase_orders_branch_id foreign key (branch_id) references branches (id);
