alter table reservations add constraint fk_reservations_branch_id foreign key (branch_id) references branches (id);
alter table reservations add constraint fk_reservations_customer_id foreign key (customer_id) references customers (id);
alter table reservations add constraint fk_reservations_table_id foreign key (table_id) references dining_tables (id);
alter table reservations add constraint fk_reservations_created_by foreign key (created_by) references staffs (id);
